"""
Writes docs/REPORT_FACTS.md from artifacts/metrics, experiments/*.json, the code and the screenshot folder.
Every document built later must agree with this file.

    python scripts/make_report_facts.py
"""
import glob
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)

from scripts.docs import facts as F  # noqa: E402

SHOT_CAPTIONS = {
    "01_landing_light": "Landing page (light theme)", "02_landing_dark": "Landing page (dark theme)", "03_login": "Sign-in form",
    "04_register": "Registration form", "05_catalog": "Course catalog (public, 24 courses)", "06_profile_first_run": "Learner profile form filled in during onboarding",
    "07_dashboard": "Dashboard after 12 recorded interactions", "08_recommendations": "Ranked recommendations with match %, success estimate and explanation",
    "09_learning_path": "Staged learning path with next best action", "10_insights": "Insights: engagement, strengths, action scores (the contributing-features list is empty for the shipped logistic regression)",
    "11_activity_interactions": "Activity log (interaction events)", "12_activity_history": "Recommendation history log", "13_catalog_signed_in": "Catalog when signed in",
    "14_course_detail": "Course detail with 'why recommended' panel and action buttons", "15_profile": "Saved learner profile", "16_analytics_models": "Model analytics: model comparison table",
    "17_analytics_diagnostics": "Model analytics: confusion matrices, ROC, feature importance", "18_analytics_policy": "Model analytics: offline policy evaluation (IPS/SNIPS/DR)",
    "19_analytics_fairness": "Model analytics: fairness audit by age band and gender", "20_dashboard_dark": "Dashboard (dark theme)",
}


def main():
    M, S, C, P, R, FB, A, L, T, E = F.METRICS, F.SEEDS, F.CEIL, F.PROFILE, F.REC, F.FB, F.ACT, F.API_LAT, F.TESTS, F.ENV
    L_ = []
    w = L_.append
    w(f"# Report facts - {F.TITLE} ({F.PRODUCT}, batch {F.BATCH_NO})\n")
    w("Single source of truth for the documentation set, generated by `scripts/make_report_facts.py` from `artifacts/metrics/model_metrics.json` and `experiments/*.json`. "
      "Every later document must agree with it. Nothing below was typed by hand except the batch details.\n")
    w("## 1. Batch\n")
    w(f"- Project: {F.TITLE}; product name {F.PRODUCT}; batch {F.BATCH_NO} ({F.SECTION}); guide {F.GUIDE} (designation not recorded -> `{F.GUIDE_DESIGNATION}`)")
    for n, r in F.STUDENTS:
        w(f"- {n} - {r}")
    w("- College, city, academic year, HOD and principal are not recorded in the batch files -> template placeholders kept (`[COLLEGE NAME]`, `[ACADEMIC YEAR]`, `[HOD NAME]`, `[PRINCIPAL NAME]`).")
    w("- Base paper: " + F.BASE_PAPER + " (PDF in `Documentary/`).")
    w("- Companion papers in `archived_base_papers/`: Khreis, Nasr, Hilal, *Isotropy-Optimized Contrastive Learning for Semantic Course Recommendation*, arXiv:2601.11427, Jan 2026 (BERT + contrastive learning on 500+ uOttawa engineering courses); "
      "Gharahighehi, Ghinis, Venturini, Cornillie, Vens, *Enhancing Collaborative Filtering-Based Course Recommendations by Exploiting Time-to-Event Information with Survival Analysis*, arXiv:2503.00072, Feb 2025.\n")

    w("## 2. What the product is (verified in the code)\n")
    w("- FastAPI backend (`app/main.py`, `app/api_routes.py`) with SQLAlchemy 2 + SQLite (`learnpathiq.db`); original Jinja2 server-rendered UI on port 8407 plus a React 19 / Vite frontend (`frontend/`, port 5407) that proxies `/api` and `/static` to the backend.")
    w("- 6 tables: `users`, `profiles` (1:1), `courses` (24 seeded from `data/catalog/courses.json`), `interactions`, `recommendation_logs`, `auth_tokens`.")
    w("- Hybrid ranker `app/recommender.py::rank_courses`: score = 0.30 content (TF-IDF cosine, `max_features=2000`, English stop words, fitted on profile + 24 course texts per request) + 0.15 skill compatibility "
      "(|level difference| 0/1/2 -> 1.0/0.6/0.3) + 0.15 topic-interest overlap + 0.12 predicted success probability + 0.10 (0.5 + behavioural boost, clipped to [-0.3, 0.35]) + 0.08 goal match (0.7/0.4) + 0.05 normalised rating + 0.05 engagement score; clipped to [0,1].")
    w("- Behavioural weights: view .05, open .06, start .12, content .10, quiz .14, forum .10, save .08, complete .20, dismiss -.25 (x event value, per course).")
    w("- Engagement score = min(1, 0.25 + 0.04 x recent events + 0.03 x quizzes + 0.08 x completions); labels Getting started (<0.4) / Steady learner (<0.7) / Highly engaged; 'Needs a nudge' if a dismiss is among the last 5 events and score < 0.45.")
    w("- Success model input (8 features): cum_clicks, recent_clicks, quiz_count, forum_count, completions, engagement, weekly_hours, skill_code. Success model shipped = the validation-AUC winner (logistic regression).")
    w("- Action scoring: one-vs-rest T-learner (two logistic regressions per action: treated vs not-treated) over quiz / content / forum / homepage / continue_course; estimated benefit = P1 - P0; `best_action = argmax`. Described as 'estimated benefit', not a proven causal effect.")
    w("- Security: pbkdf2_sha256 (29,000 rounds) password hashes, `secrets.token_urlsafe(32)` tokens stored in `auth_tokens`, HttpOnly SameSite=Lax cookie `lpq_token` (72 h) or `X-Token` / Bearer header, Pydantic v2 validation (EmailStr, length limits), ORM parameterised queries.")
    w("- Pages (React): Landing, Login, Register, Catalog, Course detail, Dashboard, Recommendations, Learning path, Insights, Activity, Profile, Model analytics (4 tabs: Models / Diagnostics / Offline policy / Fairness audit).")
    w("- Code size: app/*.py = 649 lines; frontend pages and components about 3,360 lines of JSX; tests/test_app.py 5 tests.\n")

    w("## 3. Endpoints\n")
    for ep in ["POST /api/auth/register", "POST /api/auth/login", "POST /api/auth/logout", "GET /api/me", "GET /api/profile", "PUT /api/profile", "GET /api/courses (q, category, level)", "GET /api/courses/{id}",
               "GET /api/recommendations (top_n)", "POST /api/recommendations/refresh", "POST /api/interactions (view/open/start/quiz/content/forum/complete/dismiss/save)", "GET /api/activity", "GET /api/history",
               "GET /api/learning-path", "GET /api/insights", "GET /api/metrics", "GET /api/fairness", "GET /api/health", "GET /static/{roc_curve,confusion_matrix,feature_importance}.png",
               "Jinja pages: / /register /login /onboarding /dashboard /recommendations /course/{id} /path /activity /insights /analytics"]:
        w(f"- `{ep}`" if not ep.startswith("Jinja") else f"- {ep}")
    w("")

    w("## 4. Dataset (read this before quoting any model number)\n")
    w(f"- **Source: `{M['dataset_source']}`** - a reproducible synthetic OULAD-like generator in `scripts/train_pipeline.py::acquire_data` (seed 42). The script probes the Open University Learning Analytics Dataset page but the real OULAD was NOT downloaded or used. "
      "OULAD itself (Kuzilek, Hlosta, Zdrahal 2017) is CC BY 4.0; the synthetic data carries no third-party licence.")
    w(f"- Size: {P['learners']:,} synthetic learners x {P['weeks']} weeks = {P['rows']:,} learner-week rows; 8 observable features + hidden assessment score; success rate {F.pct(P['success_rate'])}; "
      f"treatment-action counts {P['action_counts']}.")
    w(f"- Split: learner-level 80/10/10 (seed 42): train {M['train_samples']:,} rows (1,760 learners), validation {M['val_samples']:,} (220), test {M['test_samples']:,} (220); positive rate on test {F.pct(S['runs'][0]['sizes']['positive_rate_test'])}.")
    w("- Label: `success = (assess_score >= 50) AND (U < 0.55 + 0.2 (assess-50)/50)` with U uniform noise, i.e. noisy, and assess_score is NOT an observable feature of the deployed model.")
    w("- Correlation of each feature with success: " + ", ".join(f"{k} {v:.3f}" for k, v in P["corr_with_success"].items()) + ".")
    w(f"- Ceiling check: adding the hidden assessment score as a feature lifts test AUC to LR {C['with_assess_score']['logistic_regression']['test_auc']:.4f} / RF {C['with_assess_score']['random_forest']['test_auc']:.4f} / XGB {C['with_assess_score']['xgboost']['test_auc']:.4f} (shipped features: {C['shipped_features']['logistic_regression']['test_auc']:.4f} / {C['shipped_features']['random_forest']['test_auc']:.4f} / {C['shipped_features']['xgboost']['test_auc']:.4f}).")
    w("- Course catalog: 24 hand-written courses, 9 categories, levels 15 Beginner / 6 Intermediate / 2 All levels / 1 Advanced, rating 4.3-4.7, 4-30 h. No real learner-course interaction log exists; collaborative filtering over real learner histories is NOT implemented (the behavioural boost is per-learner, not cross-learner).\n")

    w("## 5. Model metrics (shipped run, seed 42, held-out test = 220 learners / 2,640 learner-weeks)\n")
    w("| Model | Val AUC | Test AUC | Accuracy | Precision | Recall | F1 | Brier | Confusion [[TN, FP],[FN, TP]] |")
    w("|---|---|---|---|---|---|---|---|---|")
    for k, v in M["models"].items():
        w(f"| {F.MODEL_LABEL[k]} | {v['val_auc']:.4f} | {v['roc_auc']:.4f} | {v['accuracy']:.4f} | {v['precision']:.4f} | {v['recall']:.4f} | {v['f1']:.4f} | {v['brier']:.4f} | {v['confusion_matrix']} |")
    w(f"\nSelected (validation AUC): **{F.MODEL_LABEL[M['selected_model']]}**. Feature importance of the selected model (|coef| on standardised inputs): " + ", ".join(f"{k} {v}" for k, v in M["feature_importance"].items()) + ".")
    w("Note: the shipped `feature_importance.png` shows absolute logistic-regression coefficients, not tree importances. `predict_success()` only returns importances for models with `feature_importances_`, so for the shipped logistic regression the API field `contributing_features` is an empty object and the Insights 'contributing features' list is empty (a small defect, stated in the documents).\n")
    w("### 5b. Six-seed re-run (seeds 42,1,2,3,4,5 re-draw the synthetic data and the learner split; artifacts untouched)\n")
    w("| Model | Test AUC mean +- sd (min-max) | F1 mean +- sd | Accuracy mean | Brier mean |")
    w("|---|---|---|---|---|")
    for k, v in S["summary"].items():
        a = v["test_auc"]
        w(f"| {F.MODEL_LABEL[k]} | {a['mean']:.4f} +- {a['std']:.4f} ({a['min']:.4f}-{a['max']:.4f}) | {v['f1']['mean']:.4f} +- {v['f1']['std']:.4f} | {v['accuracy']['mean']:.4f} | {v['brier']['mean']:.4f} |")
    w(f"\nValidation-AUC selection over the 6 seeds: {S['selected_counts']}. Seed 42 reproduces the shipped metrics exactly (LR 0.6028, RF 0.5439, XGB 0.5994).\n")

    pe = M["policy_evaluation"]
    w("## 6. Offline policy evaluation (shipped run)\n")
    w(f"- Behaviour policy: multinomial logistic regression over the 5 actions; propensities clipped to {pe['clipping']}, importance weights capped at {pe['weight_cap']}; target policy = argmax uplift per learner-week; rewards = observed success.")
    w(f"- IPS {pe['ips']}, SNIPS {pe['snips']}, Doubly Robust {pe['doubly_robust']}; effective sample size {pe['effective_sample_size']} of {pe['test_samples']:,} test rows. "
      "The huge gap between IPS (0.009) and SNIPS (0.665) and the ESS of about 9 mean the estimates are dominated by a handful of rows: NOT a reliable evidence of policy gain. Logged success rate on the test rows is 0.4375.")
    w("- Base paper for comparison (OULAD, different data and task): XGBoost AUC 0.795, Brier 0.074; logged pass rate 0.589; Greedy-Uplift SNIPS 0.619 [0.613, 0.625]; IPS 9.956 vs SNIPS 0.643 in its Table 4. Not comparable with this project (synthetic data, no RL agent).\n")

    w("## 7. Fairness audit (audit only, shipped run)\n")
    for attr, grp in M["fairness"].items():
        for g, v in grp.items():
            w(f"- {attr} = {g}: n={v['n']}, observed success {v['success_rate']:.3f}, mean predicted {v['avg_predicted']:.3f}, F1 {v['f1']:.3f}")
    w("")

    w("## 8. Recommender sanity evaluation (`scripts/run_experiments.py`, `experiments/recsys_eval.json`)\n")
    w("10 author-written learner personas; a course is 'relevant' when its category is in the persona's expected set (written down before any ranking was run). A sanity check on a 24-course catalog, NOT a user study; "
      "precision/recall against real learner feedback was not measured.\n")
    w("| Ranker | P@1 | P@3 | P@5 | MRR |")
    w("|---|---|---|---|---|")
    for k, v in R["summary"].items():
        w(f"| {k} | {v['p@1']:.2f} | {v['p@3']:.3f} | {v['p@5']:.2f} | {v['mrr']:.3f} |")
    w("\nFinding: the hybrid beats the popularity baseline by a wide margin but does NOT beat content-only TF-IDF on these personas (P@3 0.733 vs 0.800, P@5 0.54 vs 0.56); the extra terms mainly add cold-start-safe signals and behavioural adaptation.\n")
    w("Drop-one-term ablation (mean over the 10 personas):\n")
    w("| Dropped term | P@3 | P@5 | top-3 overlap with full |")
    w("|---|---|---|---|")
    for k, v in R["ablation_drop_one_term"].items():
        w(f"| {k} | {v['p@3']:.3f} | {v['p@5']:.2f} | {v.get('top3_overlap_with_full', 1.0):.2f} |")
    w("")
    w("## 9. Feedback loop and action-score behaviour\n")
    fb = FB
    w(f"- Persona 'python, data science, machine learning' (Beginner): before any event top-3 {fb['top3_before']}; after 6 events (start/quiz/quiz/complete on ML101, view DS101, dismiss DA101) top-3 {fb['top3_after']}; "
      f"ML101 score {fb['tracked']['ML101']['score_before']} -> {fb['tracked']['ML101']['score_after']}; DA101 rank 3 -> {fb['tracked']['DA101']['rank_after']}; success estimate {fb['p_success_before']:.3f} -> {fb['p_success_after']:.3f}; engagement {fb['engagement_before']['label']} -> {fb['engagement_after']['label']}.")
    w(f"- Estimated action benefits flip sign with a few events: before {fb['uplift_before']}, after {fb['uplift_after']}; best action {fb['best_action_before']} -> {fb['best_action_after']}. The uplift models extrapolate from a confounded, synthetic log.")
    w(f"- Grid of {A['grid_states']} learner states: best-action counts {A['best_action_counts']}; predicted success ranges {A['p_success_min']:.3f}-{A['p_success_max']:.3f} (mean {A['p_success_mean']:.3f}). "
      "The suggested action depends on the learner state only, so every card in one learner's list shows the same suggested action (visible in screenshot 08).\n")

    w("## 10. Performance (loopback 127.0.0.1, measured by `scripts/measure_api.py`)\n")
    w("| Endpoint | n | mean ms | median ms | p95 ms |")
    w("|---|---|---|---|---|")
    for k, v in L["endpoints"].items():
        w(f"| {k} | {v['n']} | {v['mean_ms']} | {v['median_ms']} | {v['p95_ms']} |")
    w("\nThe first registration (428 ms) includes password hashing and the first database write; recommendations are recomputed (TF-IDF fit over 25 documents + scoring 24 courses) on every call - no caching.\n")

    w("## 11. Tests\n")
    w(f"- pytest `tests/test_app.py`: {T['pytest']['collected']} tests, {T['pytest']['passed']} passed, {T['pytest']['failed']} failed, {T['pytest']['seconds']} s ({', '.join(T['pytest']['tests'])}).")
    w(f"- `scripts/smoke_test.py` (end-to-end through the Vite proxy): {T['smoke']['passed']}/{T['smoke']['checks']} checks passed.")
    w(f"- `scripts/check_responsive.py` (Playwright, Chrome): 11 screens x 3 widths (360/768/1440) x light/dark - no horizontal overflow, no console errors, no failed requests: passed={T['responsive']['passed']}.")
    w("- Not done: load testing beyond 30 sequential requests, a user study, cross-browser testing beyond Chrome, penetration testing, offline-metric validation on real OULAD.\n")

    w("## 12. Environment\n")
    w(f"- {E['os']}; {E['cpu']} ({E['cores']} cores / {E['logical_processors']} threads); {E['ram_gb']} GB RAM; no GPU used; Python {E['python']}; Node {E['node']}, npm {E['npm']}.")
    w("- Packages: " + ", ".join(f"{k} {v}" for k, v in E["packages"].items()) + ".")
    w("- Frontend: " + ", ".join(f"{k} {v}" for k, v in E["frontend_dependencies"].items()) + ".")
    w("- Training run time on this machine: a seed run (data generation + 3 models + uplift) takes about " + f"{S['runs'][0]['seconds']} s" + " (measured in the seed study, excluding OPE).\n")

    w("## 13. Screenshot inventory (`docs/screenshots/`, 1440x900, real data: one registered learner with a filled profile and 12 interaction events)\n")
    for p in sorted(glob.glob(os.path.join(F.SHOTS, "*.png"))):
        k = os.path.basename(p)[:-4]
        w(f"- `{os.path.basename(p)}` - {SHOT_CAPTIONS.get(k, k)}")
    w("\nLegacy server-rendered UI captures from the original build exist in `screenshots/` (11 files, 1280-wide); not used unless stated.\n")

    w("## 14. Gaps stated plainly\n")
    for g in [
        "The real OULAD data was never used; every metric is from the synthetic OULAD-like generator. No external-validity claim is made.",
        "Test AUC is about 0.60 (selected model 0.6028; 6-seed mean 0.614 for logistic regression): modest discrimination, because the deployed features carry little signal about the synthetic label.",
        "Offline policy values (SNIPS 0.665, DR 0.436) rest on an effective sample size of 9.1 and are not evidence that the action policy improves outcomes.",
        "No live A/B test, no user study, no precision/recall against real learner feedback (objective 6 is only partly met: persona-based precision@k and MRR on a 24-course catalog).",
        "Collaborative filtering across learners (objective 3) is not implemented; the behavioural term is per learner. Learning paths are ordered by skill level then score, not by an explicit prerequisite graph.",
        "The base paper's Actor-Critic reinforcement-learning agent and causal regularisation are not implemented; the project borrows its uplift (T-learner) + OPE + fairness-audit components only.",
        "No cache, single-node SQLite, demo-grade token auth; the app is intended for local use.",
    ]:
        w(f"- {g}")
    out = os.path.join(ROOT, "docs", "REPORT_FACTS.md")
    open(out, "w", encoding="utf-8").write("\n".join(L_) + "\n")
    print("wrote", out)


if __name__ == "__main__":
    main()
